messages.content:
Plan a tool named `make_toml_item`: Create a TOML item from a Python object.

It wraps this function:
tomlkit.item(value: Any, _parent: Item | None = None, _sort_keys: bool = False) -> Item

Docstring:
Create a TOML item from a Python object.

:Example:

>>> item(42)
42
>>> item([1, 2, 3])
[1, 2, 3]
>>> item({'a': 1, 'b': 2})
a = 1
b = 2

Source code:
```python
def item(value: Any, _parent: Item | None = None, _sort_keys: bool = False) -> Item:
    """Create a TOML item from a Python object.

    :Example:

    >>> item(42)
    42
    >>> item([1, 2, 3])
    [1, 2, 3]
    >>> item({'a': 1, 'b': 2})
    a = 1
    b = 2
    """

    from tomlkit.container import Container

    if isinstance(value, Item):
        return value

    if isinstance(value, bool):
        return Bool(value, Trivia())
    elif isinstance(value, int):
        return Integer(value, Trivia(), str(value))
    elif isinstance(value, float):
        return Float(value, Trivia(), str(value))
    elif isinstance(value, dict):
        table_constructor = (
            InlineTable if isinstance(_parent, (Array, InlineTable)) else Table
        )
        val = table_constructor(Container(), Trivia(), False)
        for k, v in sorted(
            value.items(),
            key=lambda i: (isinstance(i[1], dict), i[0]) if _sort_keys else 1,
        ):
            val[k] = item(v, _parent=val, _sort_keys=_sort_keys)

        return val
    elif isinstance(value, (list, tuple)):
        a: AoT | Array
        if (
            value
            and all(isinstance(v, dict) for v in value)
            and (_parent is None or isinstance(_parent, Table))
        ):
            a = AoT([])
            table_constructor = Table
        else:
            a = Array([], Trivia())
            table_constructor = InlineTable

        if table_constructor is Table:
            # AoT tables render as ``[[table]]`` headers, so dict-valued keys
            # must come last to avoid them capturing the following keys.
            def _sort_key(i: tuple[Any, Any]) -> Any:
                return (isinstance(i[1], dict), i[0] if _sort_keys else 1)
        else:
            # Inline tables cannot capture, so there is no need to put
            # dict-valued keys last: preserve insertion order, or sort purely
            # by key when explicitly requested. See #546.
            def _sort_key(i: tuple[Any, Any]) -> Any:
                return i[0] if _sort_keys else 1

        for v in value:
            if isinstance(v, dict):
                table = table_constructor(Container(), Trivia(), True)

                for k, _v in sorted(v.items(), key=_sort_key):
                    i = item(_v, _parent=table, _sort_keys=_sort_keys)
                    if isinstance(table, InlineTable):
                        i.trivia.trail = ""

                    table[k] = i

                v = table

            a.append(v)

        return a
    elif isinstance(value, str):
        return String.from_raw(value)
```

