Write the tool `create_date`: Create a date literal.

Its parameters, with exactly these names:
- year (integer): The year component of the date
- month (integer): The month component of the date
- day (integer): The day component of the date

It wraps this class:
tomlkit.api.Date(year: int, month: int, day: int, trivia: Trivia | None = None, raw: str = '') -> Date

Docstring:
A date literal.

Source code:
```python
class Date(Item, date):
    """
    A date literal.
    """

    def __new__(
        cls,
        year: int,
        month: int,
        day: int,
        trivia: Trivia | None = None,
        raw: str = "",
    ) -> Date:
        return date.__new__(cls, year, month, day)

    def __init__(
        self,
        year: int,
        month: int,
        day: int,
        trivia: Trivia | None = None,
        raw: str = "",
    ) -> None:
        super().__init__(trivia or Trivia())

        self._raw = raw

    def unwrap(self) -> date:
        (year, month, day, _, _) = self._getstate()
        return date(year, month, day)

    @property
    def discriminant(self) -> int:
        return 6

    @property
    def value(self) -> date:
        return self

