class String(str, Item):
    """
    A string literal.
    """

    def __new__(
        cls, t: StringType, value: str, original: str, trivia: Trivia
    ) -> String:
        return super().__new__(cls, value)

    def __init__(self, t: StringType, _: str, original: str, trivia: Trivia) -> None:
        super().__init__(trivia)

        self._t = t
        self._original = original

    def unwrap(self) -> str:
        return str(self)

    @property
    def discriminant(self) -> int:
        return 11

    @property
    def value(self) -> str:
        return self

    def as_string(self) -> str:
        return f"{self._t.value}{decode(self._original)}{self._t.value}"

    @property
    def type(self) -> StringType:
        return self._t

    def __add__(self, other: str) -> String:
        result = super().__add__(other)
        if isinstance(other, String):
            original = self._original + other._original
        else:
            escaped = self._t.escaped_sequences
            original = self._original + (
                escape_string(other, escaped) if escaped else other
            )

        return self._new(result, original)

    def _new(self, result: str, original: str) -> String:
        return String(self._t, result, original, self._trivia.copy())

    def _getstate(self, protocol: int = 3) -> tuple[StringType, str, str, Trivia]:
        return self._t, str(self), self._original, self._trivia

    @classmethod
    def from_raw(
        cls, value: str, type_: StringType = StringType.SLB, escape: bool = True
    ) -> String:
        value = decode(value)

        invalid = type_.invalid_sequences
        # collapse CRLF line endings so only a lone CR trips the CR check
        checked = value.replace("\r\n", "\n")
        if any(c in checked for c in invalid):
            raise InvalidStringError(value, invalid, type_.value)

        string_value = value
        if escape:
            string_value = escape_string(string_value, type_.escaped_sequences)
            if type_ is StringType.MLB and escape:
                string_value = _BARE_CR.sub(r"\\r", string_value)
            if type_.is_multiline() and string_value[:1] in ("\n", "\r"):
                # A newline immediately following the opening delimiter of a
                # multiline string is trimmed by the parser, so a value that
                # starts with a newline would otherwise lose it on round-trip.
                # Emit an extra leading newline (the trimmed one) to preserve it.
                string_value = "\n" + string_value

        return cls(type_, value, string_value, Trivia())
