from typing import Any, Union
import tomlkit


def make_toml_item(value: Any) -> Union[str, int, float, bool, list, dict, None]:
    """Create a TOML item from a Python object.

    Args:
        value: A Python object to convert to a TOML item

    Returns:
        A JSON-compatible representation of the TOML item

    Example:
        >>> make_toml_item(42)
        42
    """
    try:
        item_result = tomlkit.item(value)
        # Convert to JSON-compatible format
        if hasattr(item_result, 'value'):
            return item_result.value
        elif hasattr(item_result, '__iter__') and not isinstance(item_result, (str, bytes)):
            return list(item_result)
        else:
            return str(item_result)
    except Exception as e:
        raise ValueError(f"Failed to create TOML item from value {value!r}: {str(e)}")
