import tomlkit
from tomlkit.parser import parse_rfc3339
from tomlkit.items import item


def make_time(raw: str) -> str:
    """Create a TOML time. raw: A time string in RFC 3339 format, e.g. '12:30:45' -> Time object."""
    try:
        # Try to parse the raw string directly as a time
        parsed = parse_rfc3339(raw)

        # Check if it's already a time object
        if isinstance(parsed, _datetime.time):
            return str(item(parsed))

        # If it's a datetime object, extract the time component
        if hasattr(parsed, 'time') and callable(getattr(parsed, 'time')):
            time_component = parsed.time()
            return str(item(time_component))

        # If parsing didn't work as expected, try to create a time directly
        # This handles cases where parse_rfc3339 might not be working as expected
        try:
            # Try to create a time object directly from the string
            from datetime import time as time_class
            # Parse time components manually for basic formats
            if '.' in raw:
                base_time, microseconds = raw.split('.')
                hours, minutes, seconds = base_time.split(':')
                microsec = int(microseconds.ljust(6, '0')[:6])
                time_obj = time_class(int(hours), int(minutes), int(seconds), microsec)
            else:
                hours, minutes, seconds = raw.split(':')
                time_obj = time_class(int(hours), int(minutes), int(seconds))

            return str(item(time_obj))
        except:
            raise ValueError("time() only accepts time strings.")

    except Exception as e:
        raise ValueError(f"Invalid time string: {raw!r}") from e


# Helper import for type checking
from datetime import datetime as _datetime
