from typing import List, Optional


def decode_toml_string(string: str, encodings: Optional[List[str]] = None) -> dict:
    """Decode a TOML string into a Python dictionary. string: A TOML string to decode, e.g. 'key = "value"' -> {'key': 'value'}."""
    try:
        result = tomlkit.container.decode(string, encodings)
        # If the result is still a string, it means it was not parsed properly
        # We should return the parsed dictionary instead
        if isinstance(result, str):
            # Try to parse it as TOML
            return tomlkit.loads(result)
        return result
    except Exception as e:
        raise ValueError(f"Failed to decode TOML string: {str(e)}")
